public class UnlockedCard {public string id,name,traitId,awakening;public int rank,cost,row,column;public bool equipped;}
// Reads selected literal metadata only. No Lua execution or game writes.
static class UnlockReader {
 internal static Dictionary<string,string> Definitions(string path){
  var result=new Dictionary<string,string>();if(!File.Exists(path))return result;string text=File.ReadAllText(path);if(text.Length>8*1024*1024)return result;
  text=Regex.Replace(text,@"--\[\[[\s\S]*?\]\](?:--)?|--[^\r\n]*","");
  foreach(Match start in Regex.Matches(text,@"(?m)^\t([A-Za-z0-9_]+)\s*=\s*\r?\n\t\{")){
   int open=start.Index+start.Length-1,depth=0;foreach(Match token in Regex.Matches(text.Substring(open),@"""(?:\\.|[^""\\])*""|[{}]")){if(token.Value=="{")depth++;if(token.Value=="}"&&--depth==0){result[start.Groups[1].Value]=text.Substring(open,token.Index+1);break;}}
  }return result;
 }
 internal static string Field(string body,string name){var m=Regex.Match(body??"",@"(?m)^\t\t"+Regex.Escape(name)+@"\s*=\s*""([^""]+)""");return m.Success?m.Groups[1].Value:"";}
 static int Cost(string body){var m=Regex.Match(body,@"(?m)^\t\tCost\s*=\s*(\d+)");return m.Success?int.Parse(m.Groups[1].Value):body.Contains("BaseBonusMetaUpgrade")?0:1;}
 internal static readonly string[][] Aspects={
  new[]{"WeaponStaffSwing","BaseStaffAspect","StaffClearCastAspect","StaffSelfHitAspect","StaffRaiseDeadAspect"},
  new[]{"WeaponDagger","DaggerBackstabAspect","DaggerBlockAspect","DaggerHomingThrowAspect","DaggerTripleAspect"},
  new[]{"WeaponTorch","TorchSpecialDurationAspect","TorchDetonateAspect","TorchSprintRecallAspect","TorchAutofireAspect"},
  new[]{"WeaponAxe","AxeRecoveryAspect","AxeArmCastAspect","AxePerfectCriticalAspect","AxeRallyAspect"},
  new[]{"WeaponLob","LobAmmoBoostAspect","LobCloseAttackAspect","LobImpulseAspect","LobGunAspect"},
  new[]{"WeaponSuit","BaseSuitAspect","SuitHexAspect","SuitMarkCritAspect","SuitComboAspect"}};
 internal static UnlockInventory Project(object state,TraitNames names){
  var result=new UnlockInventory();var weapons=HadesSave.Get(state,"WeaponsUnlocked");var list=new List<SavedWeapon>();
  foreach(var family in Aspects){if(!object.Equals(HadesSave.Get(weapons,family[0]),true))continue;for(int i=1;i<family.Length;i++){string aspect=family[i];if(i>1&&!object.Equals(HadesSave.Get(weapons,aspect),true))continue;int rank=1;for(int n=2;n<=5;n++)if(object.Equals(HadesSave.Get(weapons,aspect+n),true))rank++;list.Add(new SavedWeapon{id=family[0],name=names.Name(family[0]),aspectId=aspect,aspectName=names.Name(aspect),aspectRank=rank});}}
  result.aspects=list.ToArray();result.grasp=(int)HadesSave.Number(HadesSave.Get(state,"MaxMetaUpgradeCostCache"));
  var definitions=Definitions(Path.Combine(names.ScriptDirectory,"MetaUpgradeData.lua"));var layout=HadesSave.Ordered(HadesSave.Get(state,"MetaUpgradeCardLayout")).ToArray();var cards=new List<UnlockedCard>();
  foreach(var item in HadesSave.Table(HadesSave.Get(state,"MetaUpgradeState"))){string id=HadesSave.Str(item.Key),body;if(!object.Equals(HadesSave.Get(item.Value,"Unlocked"),true)||!definitions.TryGetValue(id,out body))continue;string trait=Field(body,"TraitName");if(trait.Length==0)continue;var card=new UnlockedCard{id=id,name=names.Name(id),traitId=trait,rank=(int)HadesSave.Number(HadesSave.Get(item.Value,"Level")),cost=Cost(body),equipped=object.Equals(HadesSave.Get(item.Value,"Equipped"),true),awakening=Field(body,"AutoEquipText")};foreach(var row in layout)foreach(var col in HadesSave.Ordered(row.Value))if(HadesSave.Str(col.Value)==id){card.row=(int)(double)row.Key;card.column=(int)(double)col.Key;}cards.Add(card);}
  result.arcana=cards.ToArray();var pickups=HadesSave.Get(state,"LootPickups");result.gods=new[]{"Zeus","Poseidon","Apollo","Hera","Aphrodite","Demeter","Hephaestus","Hestia","Ares"}.Where(g=>HadesSave.Number(HadesSave.Get(pickups,g+"Upgrade"))>0).ToArray();return result;
 }
}
