 internal static string God(string id){string god;if(ExtraGods.TryGetValue(id,out god))return god;return new[]{"Zeus","Poseidon","Apollo","Hera","Aphrodite","Demeter","Hephaestus","Hestia","Ares"}.FirstOrDefault(g=>id.StartsWith(g,StringComparison.Ordinal))??"";}
 internal static string[] AvailableIds(BuildTarget t,SavedBuild b){return t.ids.Where(id=>Names.Name(id)!=id&&(b.unlocks.gods??new string[0]).Contains(God(id))).ToArray();}
 internal static BuildRecipe[] Available(SavedBuild b){if(b==null||b.unlocks==null)return new BuildRecipe[0];return Recipes.Where(r=>b.unlocks.aspects.Any(a=>a.aspectId==r.aspect)&&r.targets.All(t=>AvailableIds(t,b).Length>0)).OrderByDescending(r=>Matches(r,b)).ThenByDescending(r=>b.unlocks.aspects.First(a=>a.aspectId==r.aspect).aspectRank).ToArray();}
 internal static bool Matches(BuildRecipe recipe,SavedBuild b){return b!=null&&b.weapon!=null&&b.weapon.aspectId==recipe.aspect;}
 internal static BuildRecipe Selected(SavedBuild b,CoachJournal j){return b==null||j.buildProfile!=b.profile?null:Available(b).FirstOrDefault(r=>r.id==j.buildId);}
 internal static void Choose(BuildRecipe r,SavedBuild b){if(r==null||!Available(b).Any(x=>x.id==r.id))throw new Exception("This build is not confirmed available in the current profile.");var j=RunLab.Load();j.buildId=r.id;j.buildProfile=b.profile;RunLab.Save(j);Diagnostics.Log("Build plan selected: "+r.id+"; advice only, no gear recorded.");}
 internal static void Clear(){var j=RunLab.Load();j.buildId=j.buildProfile="";RunLab.Save(j);}
 internal static string SelectCommand(string text,SavedBuild b){string command=ScreenSignals.Clean(text);string prefix=new[]{"use build ","switch build to ","choose build "}.FirstOrDefault(p=>command.StartsWith(p));if(prefix==null)return null;string name=command.Substring(prefix.Length);var recipe=Available(b).FirstOrDefault(r=>ScreenSignals.Clean(r.title)==name||ScreenSignals.Clean(r.id.Replace('-',' '))==name);if(recipe==null)return "That build is not confirmed available. Open Sandbox to choose an unlocked route.";Choose(recipe,b);return "Selected "+recipe.title+". "+View(recipe,b).next;}
 internal static LabReply Brief(SavedBuild b){var r=Selected(b,RunLab.Load());if(r==null)return null;var v=View(r,b);return new LabReply{brief="Your selected route is "+r.title+". "+v.adaptation,focus=Matches(r,b)?r.rotation:"Before the next run: "+v.weapon.name+", "+v.weapon.aspectName+" at your owned rank "+v.weapon.aspectRank+". Your current run keeps its actual setup.",nextTarget=v.next,watchFor=r.limit};}
 internal static UnlockedCard[] Deck(BuildRecipe r,SavedBuild b){
  if(b==null||b.unlocks==null)return new UnlockedCard[0];var u=b.unlocks;var selected=new List<UnlockedCard>();int total=0;
  string[] priority=r.omega?new[]{"LastStand","MagicCrit","ChanneledCast","CastBuff","StatusVulnerability","BonusHealth","ScreenReroll","RarityBoost","HealthRegen","BonusDodge","SprintShield","MetaToRunUpgrade","LowManaDamageBonus"}:new[]{"LastStand","LowManaDamageBonus","CastBuff","StatusVulnerability","ScreenReroll","RarityBoost","HealthRegen","BonusHealth","BonusDodge","SprintShield","MetaToRunUpgrade","ChanneledCast"};
  foreach(string id in priority){var c=u.arcana.FirstOrDefault(a=>a.id==id&&a.cost>0);if(c!=null&&total+c.cost<=u.grasp){selected.Add(c);total+=c.cost;}}
  foreach(var c in u.arcana.Where(a=>a.cost==0)){bool active=c.id=="MaxHealthPerRoom"?Enumerable.Range(1,5).All(n=>selected.Any(a=>a.cost==n)):c.id=="SorceryRegenUpgrade"?c.row>0&&selected.Any(a=>a.row>0&&Math.Abs(a.row-c.row)<=1&&Math.Abs(a.column-c.column)<=1):c.id=="BonusRarity"?selected.Count>0&&selected.GroupBy(a=>a.cost).All(g=>g.Count()<=2):false;if(active)selected.Add(c);}
  return selected.ToArray();
 }
 internal static string CardRole(string id){switch(id){case "LastStand":return "Death Defiance reserve";case "MagicCrit":return "Omega-combo damage";case "ChanneledCast":return "faster channeling";case "CastBuff":return "damage against foes in Cast";case "StatusVulnerability":return "damage with two Olympian curses active";case "ScreenReroll":return "reroll boon choices";case "RarityBoost":return "better boon rarity odds";case "HealthRegen":return "recovery between locations";case "BonusHealth":return "Life and Magick capacity";case "BonusDodge":return "safer, quicker Cast";case "SprintShield":return "dash and sprint support";case "MetaToRunUpgrade":return "turn minor rewards into major rewards";case "LowManaDamageBonus":return "normal Attack/Special damage below full Magick";case "SorceryRegenUpgrade":return "Hex charge";case "MaxHealthPerRoom":return "Life and Magick growth";case "BonusRarity":return "Duo boon odds";default:return "check its installed in-game description";}}
 internal static string EvidenceStamp(RunRecord run){var last=run.events.LastOrDefault(e=>(e.updates??new BuildUpdate[0]).Any(u=>u.evidence!="game_state"&&new[]{"acquired","equipped","correction","preference"}.Contains(u.category)));return last==null?"":last.time;}
 static string Reported(string[] ids,SavedBuild b){var run=RunMemory.Load();DateTime checkpoint;if(run.gameState==null||run.gameState.sourceRun!=b.sourceRun||!DateTime.TryParse(b.savedAt,out checkpoint))return "";var updates=run.events.Where(e=>{DateTime t;return DateTime.TryParse(e.time,out t)&&t.ToUniversalTime()>checkpoint.ToUniversalTime();}).SelectMany(e=>e.updates??new BuildUpdate[0]).Reverse().ToArray();foreach(var u in updates){var matching=ids.Where(id=>(" "+OfferMemory.Identity(u.fact)+" ").Contains(" "+OfferMemory.Identity(Names.Name(id))+" ")).ToArray();if(matching.Length!=1)continue;if(new[]{"correction","uncertain"}.Contains(u.category))return "";if(new[]{"acquired","equipped"}.Contains(u.category)&&new[]{"player","visible"}.Contains(u.evidence))return matching[0];}return "";}
 static string CoreReport(string slot,SavedBuild b){string suffix=slot=="Melee"?"WeaponBoon":slot=="Secondary"?"SpecialBoon":slot=="Ranged"?"CastBoon":slot=="Mana"?"ManaBoon":"";return suffix.Length==0?"":Reported(new[]{"Zeus","Poseidon","Apollo","Hera","Aphrodite","Demeter","Hephaestus","Hestia","Ares"}.Select(g=>g+suffix).Where(id=>Names.Name(id)!=id).ToArray(),b);}
 static string CoreId(string slot,SavedBuild b){string report=CoreReport(slot,b);var old=(b.owned??new SavedTrait[0]).FirstOrDefault(t=>t.slot==slot&&t.category=="trait");return report.Length>0?report:old==null?"":old.id;}
 internal static BuildTarget[] EffectiveTargets(BuildRecipe r,SavedBuild b){var list=r.targets.ToList();if(Matches(r,b)&&(CoreId("Melee",b)=="HephaestusWeaponBoon"||CoreId("Secondary",b)=="HephaestusSpecialBoon")&&b.unlocks.gods.Contains("Hephaestus")&&!list.Any(t=>t.ids.Contains("MassiveDamageBoon")))list.Add(T("Support your blast","","Adapted to the blast already equipped. Develop it before forcing a replacement.","MassiveDamageBoon"));return list.ToArray();}
 internal static PlanView View(BuildRecipe r,SavedBuild b){
  var v=new PlanView{title=r.title,weapon=b.unlocks.aspects.First(a=>a.aspectId==r.aspect),cards=Deck(r,b),grasp=b.unlocks.grasp,mode=Matches(r,b)?"Guiding the equipped aspect":"Next-run setup · equipped aspect differs"};var steps=new List<PlanStep>();var owned=Matches(r,b)?b.owned??new SavedTrait[0]:new SavedTrait[0];
  var targets=EffectiveTargets(r,b);foreach(var t in targets){var ids=AvailableIds(t,b);var hit=owned.FirstOrDefault(a=>ids.Contains(a.id));string reported=Matches(r,b)?Reported(ids,b):"";string newerCore=Matches(r,b)?CoreReport(t.slot,b):"";if(newerCore.Length>0&&!ids.Contains(newerCore))hit=null;var occupied=t.slot.Length==0?null:owned.FirstOrDefault(a=>a.slot==t.slot&&a.category=="trait");if(newerCore.Length>0)occupied=new SavedTrait{name=Names.Name(newerCore)};string state=reported.Length>0?"REPORTED":hit!=null?(hit.id==ids[0]?"OWNED":"ADAPTED"):occupied!=null?"COMPARE":"SEEK";steps.Add(new PlanStep{role=t.role,status=state,target=reported.Length>0?Names.Name(reported):hit!=null?hit.name+(!string.IsNullOrEmpty(hit.rarity)?" ("+hit.rarity+")":""):Names.Name(ids[0]),alternatives=ids.Skip(1).Select(Names.Name).ToArray(),why=reported.Length>0?"Recorded after the checkpoint from a player report or confirmed visual pickup. Autosave has not caught up; no repeat confirmation needed.":hit!=null?"Confirmed equipped in the save. "+t.why:occupied!=null?"You have "+occupied.name+". Keep it unless an actual offer wins on damage, conditions and lost synergies.":t.why});}
  v.steps=steps.ToArray();var pending=steps.FirstOrDefault(s=>s.status=="SEEK");v.next=!Matches(r,b)?"Equip the listed weapon and aspect before a new run. Current-run coaching continues from your actual equipment.":pending!=null?pending.role+": look for "+pending.target+" or a listed alternative.":steps.Any(s=>s.status=="COMPARE")?"Your slots are filled. Compare support and upgrades before replacing a strong core.":"Core targets are equipped. Prioritize efficient upgrades, compatible support and survival.";
  v.adaptation=!Matches(r,b)?"Weapon and Arcana changes are pre-run advice. Selecting this route does not equip or acquire anything.":steps.Any(s=>s.status=="ADAPTED")?"An accepted alternative is already equipped. The route now builds around it; the original target is optional.":steps.Any(s=>s.status=="COMPARE")?"Your actual core differs from the recipe. Preserve its investment and compare the next real offer; do not force a replacement.":"Progress updates from your game-save checkpoint. Boons offered on screen are never counted as owned.";
  int nextIndex=Array.FindIndex(v.steps,s=>s.status=="SEEK");var nextTarget=nextIndex<0?null:targets[nextIndex];var god=nextTarget==null?"":God(AvailableIds(nextTarget,b)[0]);var keepsake=(Matches(r,b)?KeepsakePlanner.Candidates(b):b.keepsakes??new SavedKeepsake[0]).FirstOrDefault(k=>k.id=="Force"+god+"BoonKeepsake");v.keepsake=nextTarget==null?"Your core slots are covered. Use the keepsake-menu coach to compare currently available support and protection.":keepsake==null?"No available owned keepsake confirms a way to target the next god. Use the keepsake-menu coach for your available alternatives.":keepsake.name+" · increases access to "+god+". Only swap at an eligible keepsake menu; the menu's locks take precedence.";return v;
 }
 internal static object Context(SavedBuild b,CoachJournal j){var r=Selected(b,j);if(r==null)return null;var v=View(r,b);return new{recipe=r.id,r.title,r.description,r.strength,r.rotation,r.limit,source=r.source,researched=ResearchDate,actualAspectMatches=Matches(r,b),plan=v};}
 internal static string Describe(BuildRecipe r,SavedBuild b){var v=View(r,b);var s=new StringBuilder();s.AppendLine(r.description+"\r\n");s.AppendLine("BEST AT\r\n"+r.strength+"\r\n");s.AppendLine("YOUR SETUP\r\n"+v.weapon.name+" · "+v.weapon.aspectName+" · owned rank "+v.weapon.aspectRank+"\r\n"+v.mode+"\r\n");s.AppendLine("HOW TO PLAY\r\n"+r.rotation+"\r\n");s.AppendLine("NEXT MOVE\r\n"+v.next+"\r\n"+v.adaptation+"\r\n");s.AppendLine("BOON ROUTE · SAVE + CONFIRMED RECENT REPORTS");foreach(var step in v.steps){s.AppendLine(step.status+"  ·  "+step.role+" — "+step.target);s.AppendLine(step.why);if(step.alternatives.Length>0)s.AppendLine("Alternatives: "+string.Join(", ",step.alternatives));s.AppendLine();}
  s.AppendLine("ARCANA TO EQUIP BEFORE THE RUN · "+v.cards.Sum(c=>c.cost)+" / "+v.grasp+" GRASP");foreach(var c in v.cards)s.AppendLine(c.name+" · rank "+c.rank+" · "+c.cost+" Grasp · "+CardRole(c.id)+(c.cost==0?" (awakening satisfied by this deck)":""));s.AppendLine("\r\nThis uses only unlocked cards and your current ranks. It is a recommended deck; the active build remains whatever the game save reports.");s.AppendLine("\r\nKEEPSAKE\r\n"+v.keepsake);if(r.hammers.Length>0)s.AppendLine("\r\nHAMMERS TO CONSIDER\r\n"+string.Join(", ",r.hammers.Select(Names.Name))+". Optional offer-dependent upgrades; verify compatibility and Magick cost in the actual menu.");s.AppendLine("\r\nTRADEOFF\r\n"+r.limit);s.AppendLine("\r\nCOMMUNITY REFERENCE · researched "+ResearchDate+"\r\n"+r.source+"\r\nUnlock-constrained advice, not a verified record build. Installed game text and current offers take precedence over older guides.");return s.ToString();}
}
class SandboxPanel : UserControl {
 readonly TrainingPanel training;readonly BuildPickerPanel picker;readonly Panel pages;
 internal RichTextBox Result{get{return training.Result;}}
 internal SandboxPanel(Func<string,bool,System.Threading.Tasks.Task> execute,Action<string> ask){Dock=DockStyle.Fill;BackColor=Theme.Bg;ForeColor=Theme.Text;Padding=new Padding(20);pages=new Panel{Dock=DockStyle.Fill};var tabs=Theme.Flow();tabs.Dock=DockStyle.Top;var buildButton=Theme.Action("Pick your build","layers","Explore routes compatible with your unlocked equipment.",(s,e)=>ShowPage(false));var trainingButton=Theme.Action("Run check-ins","flask","Create a local briefing, compare progress, or review the last attempt.",(s,e)=>ShowPage(true));tabs.Controls.Add(buildButton);tabs.Controls.Add(trainingButton);Controls.Add(pages);Controls.Add(tabs);training=new TrainingPanel(execute,ask){Padding=new Padding(0,12,0,0)};picker=new BuildPickerPanel(ask);pages.Controls.Add(training);pages.Controls.Add(picker);ShowPage(false);}
 void ShowPage(bool lab){if(training==null||picker==null)return;training.Visible=lab;picker.Visible=!lab;(lab?(Control)training:picker).BringToFront();}
 internal void RefreshBuild(){picker.RefreshBuild();}
}
}
